<?php
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('X-Robots-Tag: noindex, nofollow, noarchive');
header('Referrer-Policy: same-origin');
require __DIR__.'/app/bootstrap.php';
$returnKey=login_return_key();
$u=current_user();if(!$u){header('Location:login.php'.login_return_query($returnKey));exit;}
$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$pin=trim((string)($_POST['pin']??''));
    try{
        register_trusted_device((int)$u['id'],$pin);
        if(($u['role']??'')==='pr')try_auto_link_pr_account((int)$u['id']);
        unset($_SESSION['needs_pin_setup']);
        header('Location:'.login_success_target($u,$returnKey));exit;
    }catch(Throwable $e){$err=$e->getMessage();}
}
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover,interactive-widget=resizes-content"><meta name="theme-color" content="#070812"><title>ตั้ง PIN — MR BAR TIME</title><style>
:root{--bg:#05060b;--panel:#0e101b;--violet:#8b3dff;--blue:#2f8cff;--text:#fff;--muted:#9493a3}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 20% 20%,#51208b55,transparent 36%),radial-gradient(circle at 85% 80%,#064e8755,transparent 35%),#05060b;color:var(--text);font-family:MRBAR Thai,Noto Sans Thai,Tahoma,Leelawadee UI,Thonburi,Segoe UI,Arial,sans-serif}.card{width:min(94vw,460px);padding:32px;border:1px solid #8a55ff44;border-radius:28px;background:#0b0d17e8;box-shadow:0 30px 100px #000a,0 0 80px #722cff20}.badge{display:inline-flex;padding:7px 10px;border:1px solid #ffffff17;border-radius:99px;font-size:10px;color:#bbb7c8;letter-spacing:1px}.icon{font-size:40px;margin:22px 0 8px}.card h1{font-size:32px;margin:0 0 8px}.card p{color:var(--muted);line-height:1.7;font-size:13px}.who{padding:13px 14px;background:#ffffff06;border:1px solid #ffffff10;border-radius:14px;margin:18px 0}.field{margin:13px 0}.field label{display:block;font-size:10px;letter-spacing:1px;color:#aaa6b8;margin-bottom:7px;font-weight:800}.pin{width:100%;height:62px;border-radius:15px;border:1px solid #ffffff18;background:#050711;color:#fff;font-size:28px;letter-spacing:12px;text-align:center;outline:none}.pin:focus{border-color:#5ea9ff99;box-shadow:0 0 0 4px #2c89ff12,0 0 35px #4f58ff20}.btn{width:100%;height:56px;border:0;border-radius:14px;background:linear-gradient(90deg,#8c35ef,#2879ee);color:#fff;font-weight:900;cursor:pointer;margin-top:8px}.err{padding:11px 12px;border-radius:12px;border:1px solid #ff4d7d44;background:#ff3c6c12;color:#ff9ab8;font-size:12px}.skip{display:block;text-align:center;color:#8e8a9b;margin-top:16px;font-size:11px;text-decoration:none}.note{font-size:10px!important;color:#777584!important;margin-top:18px!important}.pin-hint{display:block;margin-top:8px;color:#78778a;font-size:10px;line-height:1.5;letter-spacing:0}.btn:disabled{opacity:.42;filter:saturate(.3);cursor:not-allowed}</style><link rel="stylesheet" href="assets/staff-auth-v12721.css?v=12721"></head><body class="staff-pin-page"><main class="card"><span class="badge">TRUSTED DEVICE SETUP</span><div class="icon">⌁</div><h1>ตั้ง PIN 6 หลัก</h1><p>กรอก PIN 6 หลักเพียงครั้งเดียวสำหรับอุปกรณ์นี้ ครั้งถัดไปเข้า MR BAR TIME ได้ด้วย PIN โดยไม่ต้องพิมพ์ Username และ Password ใหม่</p><div class="who"><b><?=h($u['display_name'])?></b><br><small><?=h(strtoupper($u['role']))?> · <?=h($u['username'])?></small></div><?php if($err):?><div class="err"><?=h($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><?php if($returnKey!==''):?><input type="hidden" name="return_to" value="<?=h($returnKey)?>"><?php endif;?><div class="field"><label>PIN 6 DIGITS · กรอกครั้งเดียว</label><input class="pin" id="pinInput" name="pin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="new-password" aria-describedby="pinHint" required><small id="pinHint" class="pin-hint">ใช้ตัวเลข 6 หลักที่จำง่ายสำหรับคุณ แต่ไม่ควรเป็นเลขเดาง่าย เช่น 111111</small></div><button class="btn" id="pinSave" disabled>SAVE PIN & CONTINUE →</button></form><a class="skip" href="<?=h(login_success_target($u,$returnKey))?>">ข้ามตอนนี้</a><p class="note">ระบบเก็บ PIN แบบ Hash และเก็บ Token อุปกรณ์ใน Secure/HttpOnly cookie ไม่เก็บ Password ของคุณเป็นข้อความธรรมดา</p></main><script>(function(){var pin=document.getElementById('pinInput'),btn=document.getElementById('pinSave');if(!pin||!btn)return;function sync(){pin.value=pin.value.replace(/\D/g,'').slice(0,6);btn.disabled=pin.value.length!==6;}pin.addEventListener('input',sync);sync();})();</script><script src="assets/staff-auth-v12721.js?v=12721"></script></body></html>
